{"function":"() => {
// list focusable elements in sequential order (deep)
const out=[];
const walk=(root)=>{root.querySelectorAll('*').forEach(e=>{ if(e.shadowRoot) walk(e.shadowRoot); if(e.tabIndex>=0 && !e.disabled && e.offsetParent!==null){ const r=e.getBoundingClientRect(); out.push(e.tagName+'|'+(e.getAttribute('aria-label')||'')+'|'+(e.innerText||e.value||'').trim().slice(0,30)+'|'+Math.round(r.x)+','+Math.round(r.y)+','+Math.round(r.width)+'x'+Math.round(r.height));}});};
walk(document);
const th=document.querySelector('thead th');
return {n:out.length, out, thCursor:getComputedStyle(th).cursor, icon:getComputedStyle(th.querySelector('br-icon-base')).cursor};
}"}

